#[must_use]
pub fn get_loot_table(key: &str) -> Option<&'static LootTable> {
    LOOT_TABLES_BY_KEY
        .binary_search_by_key(&key, |&(key, _)| key)
        .ok()
        .map(|index| LOOT_TABLES_BY_KEY[index].1)
}
#[must_use]
pub fn get_loot_predicate(key: &str) -> Option<&'static LootPredicateValue> {
    match key {
        "minecraft:block/fast_cooking" => Some(&LOOT_NAMED_PREDICATE_0),
        "minecraft:tool/can_shear" => Some(&LOOT_NAMED_PREDICATE_1),
        "minecraft:tool/can_silk_touch" => Some(&LOOT_NAMED_PREDICATE_2),
        _ => None,
    }
}
#[must_use]
pub fn get_chest_loot_table(key: &str) -> Option<&'static LootTable> {
    get_loot_table(key)
}
